window.GuanwuRoutePlanner=(()=>{
 const savedKey='guanwu-city-routes-v1',drafts={};let map=null,mapRoute='',mapFrame=0;
 const valid=id=>{const p=GUANWU_LOCATIONS[id];return p&&!p.unavailable&&Number.isFinite(p.lat)&&Number.isFinite(p.lng)?p:null};
 const locations=()=>GUANWU_LOCATIONS;
 const routeStore=()=>stored(savedKey,{});
 function draft(c){if(!drafts[c.id])drafts[c.id]={name:c.city+'的博物之旅',date:'',start:'09:30',gap:30,mode:'transit',durations:{},...(routeStore()[c.id]||{})};return drafts[c.id]}
 const load=id=>routeStore()[id]||null;
 const modeName=m=>({walk:'步行',transit:'公交',driving:'驾车'}[m]||'公交');
 function navigation(a,b,mode){const params=new URLSearchParams({output:'html',mode:({walk:'walking',transit:'transit',driving:'driving'}[mode]||'transit'),coord_type:'wgs84',region:b.city,src:'webapp.guanwu.museum'});const endpoint=m=>{const p=valid(m.id);return p?`latlng:${p.lat},${p.lng}|name:${p.label}`:m.fullName+' '+m.address};params.set('origin',endpoint(a));params.set('destination',endpoint(b));return 'https://api.map.baidu.com/direction?'+params}
 function pointLink(m){const p=valid(m.id);if(!p)return 'https://uri.amap.com/search?'+new URLSearchParams({keyword:m.fullName+' '+m.address,city:m.city,callnative:'0'});return 'https://api.map.baidu.com/marker?'+new URLSearchParams({location:p.lat+','+p.lng,title:p.label,content:m.address,coord_type:'wgs84',output:'html',src:'webapp.guanwu.museum'})}
 function panel(c,selected){const d=draft(c);return `<section class="map-planner"><div class="map-planner-heading"><div><div class="eyebrow">YOUR CITY, YOUR ROUTE</div><h2>在地图上，安排自己的下一站。</h2></div><button class="outline-btn" data-route-fit>⌖ 看完整路线</button></div><div class="map-transport" aria-label="出行方式">${[['transit','公交'],['walk','步行'],['driving','驾车']].map(([id,name])=>`<button data-route-mode="${id}" data-route-city="${c.id}" class="${d.mode===id?'active':''}" aria-pressed="${d.mode===id}">${name}</button>`).join('')}<span>交通方案在导航中实时计算</span></div><div class="city-map" id="city-map" role="region" aria-label="${c.city}博物馆地图"><div class="map-loading">正在准备场馆地图…</div></div><div class="map-legend"><span><i></i>选中的场馆</span><span><i class="available"></i>本城其他馆</span><span><i class="dashed"></i>参观顺序示意</span></div><p class="map-disclaimer">虚线仅连接场馆参考点，不是道路路线或入口位置。选择站点后，可逐段打开导航查看真实路线；不提供未经核实的交通耗时。</p><details class="map-sources"><summary>坐标与地图来源</summary>${c.museums.map(m=>{const p=locations()[m.id];return `<p><strong>${m.name}：</strong>${esc(p?.accuracyNote||'坐标待核实，先按中文地址查询')} ${p?.source?.url?`<a href="${esc(p.source.url)}" target="_blank" rel="noopener">${esc(p.source.title)} ↗</a>`:''}</p>`}).join('')}<a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors</a> · <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noopener">反馈地图问题 ↗</a></details></section>`}
 function clock(minutes){return String(Math.floor(minutes/60)%24).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0')}
 function schedule(c,selected){const d=draft(c),[hh,mm]=d.start.split(':').map(Number);let cursor=(hh||0)*60+(mm||0);return selected.length?selected.map((m,i)=>{const stay=Math.max(15,Math.min(360,Number(d.durations[m.id])||90)),start=cursor;cursor+=stay;const text=`<div class="route-time-row"><span>${clock(start)}–${clock(cursor)}${Math.floor(cursor/1440)>0?' · 第'+(Math.floor(cursor/1440)+1)+'天':''}</span><strong>${m.name}</strong><label>停留 <input type="number" min="15" max="360" step="15" value="${stay}" data-route-stay="${m.id}" data-route-city="${c.id}" aria-label="${m.name}停留分钟"> 分钟</label></div>`;if(i<selected.length-1)cursor+=Number(d.gap)||0;return text+(i<selected.length-1?`<div class="route-leg"><p>自行预留 ${Number(d.gap)||0} 分钟交通 / 休息（非预测）</p><a href="${esc(navigation(m,selected[i+1],d.mode))}" target="_blank" rel="noopener">第 ${i+1} 站 → 第 ${i+2} 站 · ${modeName(d.mode)}实际路线 ↗</a></div>`:'')}).join(''):'<p class="tiny-note">先选一家馆，再安排参观顺序。</p>'}
 function editor(c,selected){const d=draft(c);return `<section class="personal-route-editor"><h3>给这次出发，留自己的安排。</h3><label>路线名字<input maxlength="60" value="${esc(d.name)}" data-route-field="name" data-route-city="${c.id}" aria-label="路线名字"></label><div class="route-date-time"><label>计划日期<input type="date" value="${esc(d.date)}" data-route-field="date" data-route-city="${c.id}" aria-label="路线计划日期"></label><label>开始时间<input type="time" value="${esc(d.start)}" data-route-field="start" data-route-city="${c.id}" aria-label="路线开始时间"></label></div><label>两站之间自行预留交通与休息（分钟）<input type="number" min="0" max="240" step="5" value="${Number(d.gap)||0}" data-route-field="gap" data-route-city="${c.id}" aria-label="两站之间预留分钟"></label><p class="tiny-note">这里只是你的时间预算；请用导航核对实际交通时间，再调整。停留时长也可在下方修改。</p><div class="route-timetable" data-route-timetable="${c.id}">${schedule(c,selected)}</div><div class="route-save-state" role="status">${d.updatedAt?'已有保存版本 · 修改后请重新保存':'尚未保存 · 完成后点击下方保存路线'}</div></section>`}
 function stopControls(c,m,index,count){return `<span class="route-reorder"><button data-route-move="${m.id}" data-route-delta="-1" data-route-city="${c.id}" ${index===0?'disabled':''} aria-label="上移${m.name}">↑</button><button data-route-move="${m.id}" data-route-delta="1" data-route-city="${c.id}" ${index===count-1?'disabled':''} aria-label="下移${m.name}">↓</button><button data-route-remove="${m.id}" data-route-city="${c.id}" aria-label="从路线移除${m.name}">×</button></span>`}
 function save(c,selected,pace){const all=routeStore(),d=draft(c);all[c.id]={...d,name:d.name.trim()||c.city+'的博物之旅',ids:selected.map(m=>m.id),pace,updatedAt:new Date().toISOString()};persist(savedKey,all);drafts[c.id]=all[c.id];document.querySelector('.route-save-state')?.replaceChildren(document.createTextNode('✓ 路线已保存到“我的手记”'));return all[c.id]}
 function publicRoute(c){const selected=GuanwuExperience.getCityPlan(c.id)?.selected||[];return {name:draft(c).name,ids:selected.map(m=>m.id),mode:draft(c).mode}}
 function saved(){const entries=Object.entries(routeStore());return entries.length?`<section class="section">${head('自己安排的城市路线','MY CITY ROUTES')}<div class="saved-city-routes">${entries.map(([id,r])=>{const c=GuanwuExperience.cities().find(c=>c.id===id);if(!c)return '';return `<article><small>${c.city} · ${modeName(r.mode)} · ${r.date||'日期待定'}</small><h3><a href="#city/${id}">${esc(r.name)} ↗</a></h3><p>${r.ids.map(id=>museums.find(m=>m.id===id)?.name||'').join(' → ')}</p><div><button class="text-link" data-route-copy="${id}">复制路线清单 ↗</button><button class="text-link" data-route-share="${id}">发布到同行交流 ↗</button><button class="text-link" data-route-delete="${id}">删除路线</button></div></article>`}).join('')}</div></section>`:''}
 function share(id){const r=routeStore()[id],c=GuanwuExperience.cities().find(c=>c.id===id);if(!r||!c)return;window.GuanwuCommunity?.compose({city:c.city,topic:'行程',route:{name:r.name,ids:r.ids,mode:r.mode},title:r.name,body:'我想按这个顺序慢慢看：\n'+r.ids.map((id,i)=>(i+1)+'. '+museums.find(m=>m.id===id).name).join('\n')+'\n\n有什么观看建议？'});}
 function importRoute(r){if(!r||!Array.isArray(r.ids)||!r.ids.length)return;const ms=r.ids.map(id=>museums.find(m=>m.id===id));if(ms.some(m=>!m)||new Set(ms.map(m=>m.city)).size!==1)return;const c=GuanwuExperience.cities().find(c=>c.city===ms[0].city);drafts[c.id]={...draft(c),name:r.name,mode:r.mode};GuanwuExperience.setCityPlan(c.id,r.ids,'custom');location.hash='city/'+c.id;render();toast('已放入你的路线草稿，可改顺序与时间；保存后会留在自己的手记。')}
 function draw(c,selected){const container=document.getElementById('city-map');if(!container)return;if(!window.L){container.innerHTML='<div class="map-loading">地图组件暂未加载，仍可按地址保存规划与打开导航。</div>';return}if(map){map.remove();map=null}container.innerHTML='';map=L.map(container,{scrollWheelZoom:false,attributionControl:true});mapRoute=c.id;
  const tile=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors',referrerPolicy:'strict-origin-when-cross-origin',updateWhenIdle:true,keepBuffer:0});if(navigator.onLine)tile.addTo(map);else container.insertAdjacentHTML('afterend','<p class="map-tile-error">底图需要联网；已保存的场馆与路线仍可阅读。</p>');let errors=0;tile.on('tileerror',()=>{if(++errors>=3){const hint=container.parentNode.querySelector('.map-tile-error');if(!hint){const node=document.createElement('p');node.className='map-tile-error';node.textContent='底图暂未加载，场馆点和地址仍可查看，也可以直接打开导航。';container.after(node)}}});
  const points=[];for(const m of c.museums){const p=valid(m.id);if(!p)continue;points.push([p.lat,p.lng]);const index=selected.findIndex(x=>x.id===m.id),marker=L.marker([p.lat,p.lng],{icon:L.divIcon({className:'guanwu-map-pin '+(index>=0?'selected':''),html:`<span>${index>=0?index+1:'＋'}</span>`,iconSize:[34,40],iconAnchor:[17,36]}),title:m.name,keyboard:true});const popup=document.createElement('div');popup.className='map-popup';popup.innerHTML=`<strong>${esc(m.name)}</strong><p>${esc(p.label||m.address)}</p><small>场馆参考点 · 非入口定位</small><div><button data-city-pick="${m.id}" data-city-id="${c.id}">${index>=0?'从本次选择移除':'加入本次选择'}</button><a href="${esc(pointLink(m))}" target="_blank" rel="noopener">在地图中查看 ↗</a></div>`;marker.bindPopup(popup).addTo(map)}
  selected.forEach((m,i)=>{if(i===selected.length-1)return;const a=valid(m.id),b=valid(selected[i+1].id);if(a&&b)L.polyline([[a.lat,a.lng],[b.lat,b.lng]],{color:'#a37d56',weight:3,dashArray:'7 8',opacity:.8}).addTo(map)});
  if(points.length)map.fitBounds(points,{padding:[38,38],maxZoom:13});else{map.setView([35,105],4);container.insertAdjacentHTML('beforeend','<p class="map-tile-error">本城坐标仍在核对，请先按地址规划。</p>')}container.dataset.ready='true';}
 function mount(route){cancelAnimationFrame(mapFrame);if(!route.startsWith('city/')){if(map){map.remove();map=null}return}mapFrame=requestAnimationFrame(()=>{const id=route.split('/')[1],plan=GuanwuExperience.getCityPlan(id);if(plan)draw(plan.city,plan.selected)})}
 function updateTimetable(id){const plan=GuanwuExperience.getCityPlan(id),el=document.querySelector(`[data-route-timetable="${id}"]`);if(plan&&el)el.innerHTML=schedule(plan.city,plan.selected);const status=document.querySelector('.route-save-state');if(status)status.textContent='修改尚未保存 · 点击下方保存路线'}
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-route-fit')&&map){const c=GuanwuExperience.getCityPlan(mapRoute)?.city;if(c){const ps=c.museums.map(m=>valid(m.id)).filter(Boolean).map(p=>[p.lat,p.lng]);if(ps.length)map.fitBounds(ps,{padding:[38,38],maxZoom:13})}}
  if(b.dataset.routeMode){const c=GuanwuExperience.getCityPlan(b.dataset.routeCity)?.city;if(c){draft(c).mode=b.dataset.routeMode;render(false)}}
  if(b.dataset.routeMove||b.dataset.routeRemove){const id=b.dataset.routeCity,plan=GuanwuExperience.getCityPlan(id),ids=plan.selected.map(m=>m.id),target=b.dataset.routeMove||b.dataset.routeRemove,index=ids.indexOf(target);if(b.dataset.routeRemove)ids.splice(index,1);else{const to=index+Number(b.dataset.routeDelta);if(to>=0&&to<ids.length)[ids[index],ids[to]]=[ids[to],ids[index]]}GuanwuExperience.setCityPlan(id,ids,'custom');render(false)}
  if(b.dataset.routeCopy){const r=routeStore()[b.dataset.routeCopy];copyText(r.name+'\n'+r.ids.map((id,i)=>{const m=museums.find(m=>m.id===id);return `${i+1}. ${m.name}\n${m.address}\n${m.official}`}).join('\n\n')+'\n\n顺序为个人规划，出发前核对馆区、开放与预约。','路线清单已复制')}
  if(b.dataset.routeShare)share(b.dataset.routeShare);
  if(b.dataset.routeDelete)dialog(`<h2 id="modal-title">删除这条城市路线？</h2><p>只删除当前浏览器保存的路线，不会删除你已经发布的帖子。</p><button class="solid-btn" data-confirm-route-delete="${b.dataset.routeDelete}">确认删除路线</button>`);
  if(b.dataset.confirmRouteDelete){const all=routeStore();delete all[b.dataset.confirmRouteDelete];persist(savedKey,all);delete drafts[b.dataset.confirmRouteDelete];document.querySelector('#modal').close();render(false)}
 });
 document.addEventListener('input',e=>{const el=e.target,id=el.dataset.routeCity;if(!id||(!el.dataset.routeField&&!el.dataset.routeStay))return;const c=GuanwuExperience.getCityPlan(id)?.city;if(!c)return;const d=draft(c);if(el.dataset.routeField){const field=el.dataset.routeField;d[field]=field==='gap'?Math.max(0,Math.min(240,Number(el.value)||0)):el.value}else d.durations[el.dataset.routeStay]=Math.max(15,Math.min(360,Number(el.value)||90));if(el.dataset.routeField==='name'||el.dataset.routeField==='date'){const status=document.querySelector('.route-save-state');if(status)status.textContent='修改尚未保存 · 点击下方保存路线'}else if(el.dataset.routeField==='start'||el.dataset.routeField==='gap')updateTimetable(id)});
 document.addEventListener('change',e=>{if(e.target.dataset.routeStay)updateTimetable(e.target.dataset.routeCity)});
 window.addEventListener('online',()=>{if(location.hash.startsWith('#city/'))mount(location.hash.slice(1))});
 return {panel,editor,stopControls,save,load,saved,mount,navigation,pointLink,publicRoute,importRoute};
})();
